def find_lcm(a, b):
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a
    return a * b // gcd(a, b)
print(find_lcm(12, 15))

def calculate_percentage(number, percentage):
    return (percentage / 100) * number
print(calculate_percentage(120, 25))

def calculate_simple_interest(principal, rate, time):
    interest = principal * rate * time
    return interest

def calculate_compound_interest(principal, rate, time, n):
    amount = principal * (1 + rate/n)**(n*time)
    return amount

def simplify_ratio(num1, num2):
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a
    common_divisor = gcd(num1, num2)
    return num1 // common_divisor, num2 // common_divisor
print(simplify_ratio(6, 8))  # Output: (3, 4)

def calculate_square(num):
    return num ** 2
print(calculate_square(5))

def calculate_cube(num):
    return num ** 3
print(calculate_cube(3))

def calculate_percentage(num, percentage):
    return (num * percentage) / 100
print(calculate_percentage(200, 25))
